const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state=FarmData.load();state??={plots:[{id:12,name:'Мои сладкие томаты',crop:'Томаты черри',sign:'Грядка Павла',size:6},{id:24,name:'Зелень к завтраку',crop:'Салат и пряные травы',sign:'Растёт с любовью',size:4}],tasks:[],cart:[],products:[]};const save=()=>FarmData.save(state);const photos=['https://images.unsplash.com/photo-1592841200221-a6898f307baa?auto=format&fit=crop&w=900&q=80','https://images.unsplash.com/photo-1416879595882-3373a0480b5b?auto=format&fit=crop&w=900&q=80'];let category='Все';const products=[{name:'Томаты с ветки',cat:'Продукты',price:280,unit:'кг',icon:'🍅'},{name:'Семена базилика',cat:'Семена',price:95,unit:'пакет',icon:'🌱'},{name:'Биогумус',cat:'Удобрения',price:390,unit:'5 л',icon:'🌿'},{name:'Морковь молодая',cat:'Продукты',price:120,unit:'кг',icon:'🥕'},{name:'Семена редиса',cat:'Семена',price:80,unit:'пакет',icon:'🌱'},{name:'Компост зрелый',cat:'Удобрения',price:250,unit:'10 л',icon:'🌾'}];function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}function modalForm(title,html,submit){$('#fields').innerHTML=`<h2>${title}</h2>${html}`;$('#form').onsubmit=e=>{e.preventDefault();submit(new FormData(e.target));save();modal.close();render()};modal.showModal()}function card(p,i){return `<article class="card"><div class="photo" style="background-image:url('${photos[i%2]}')"><span class="badge">● КАМЕРА ${p.id} · ДЕМО</span><span class="tag">${esc(p.sign)}</span></div><div class="cardbody"><div class="row"><h3>${esc(p.name)}</h3><small>№ ${p.id}</small></div><small>${esc(p.crop)} · ${p.size} м² · Ферма «Зелёный луг»</small><div class="metrics"><span>◉ Влажность 64%</span><span>☀ +24°C</span><span>♧ День 32</span></div><div class="actions"><button class="btn" onclick="camera(${p.id})">▷ Смотреть камеру</button><button class="btn light" onclick="care(${p.id})">Управлять</button><button class="btn light" onclick="sign(${p.id})">Табличка</button></div></div></article>`}function heading(t,p,b=''){return `<div class="heading"><div><h1>${t}</h1><p>${p}</p></div>${b}</div>`}function home(){return heading('Своё ближе, чем кажется.','Твоё хозяйство растёт. Заглянем, как там дела?','<a href="#rent" class="btn">＋ Добавить грядку</a>')+`<section class="hero"><span class="eyebrow">ТВОЯ ЗЕМЛЯ. ТВОИ ПРАВИЛА.</span><h2>Из маленького семечка —<br>в большую заботу о себе.</h2><p>Выращивай своё. Наблюдай из любой точки мира.</p><a href="#rent" class="btn">Найти свою грядку ↗</a></section><div class="stats"><div class="stat"><small>МОИ ГРЯДКИ</small><strong>${state.plots.length} <small>участка</small></strong><small>В одном личном хозяйстве</small></div><div class="stat"><small>ПЛОЩАДЬ</small><strong>${state.plots.reduce((a,p)=>a+p.size,0)} <small>м²</small></strong><small>Для любимых продуктов</small></div><div class="stat"><small>ЗАДАНИЯ ФЕРМЕРУ</small><strong>${state.tasks.filter(t=>!t.done).length}</strong><small>Ожидают выполнения · демо</small></div><div class="stat"><small>ДО ПЕРВОГО УРОЖАЯ</small><strong>~18 <small>дней</small></strong><small>Пример прогноза</small></div></div><div class="sectiontitle"><h2>Мои грядки <small> / ${state.plots.length}</small></h2><a href="#rent">Все участки ↗</a></div><div class="grid">${state.plots.map(card).join('')}</div><div class="lower"><section class="panel"><h3>Дневник хозяйства</h3>${state.tasks.slice(-4).reverse().map(t=>`<div class="event">${esc(t.text)} · Грядка №${t.plot}<small>${t.done?'Выполнено':'В очереди'} · демонстрационная запись</small></div>`).join('')||'<div class="event">Добро пожаловать в своё хозяйство<small>Создай первое задание через кнопку «Управлять»</small></div>'}</section><section class="panel promo"><small>СЛЕДУЮЩАЯ ГЛАВА</small><h2>Хозяйство больше<br>одной грядки.</h2><p>В будущем — куры, козы и другие животные с собственным дневником ухода.</p><a href="#animals" class="btn light">Что дальше ↗</a></section></div>`}function rent(){return heading('Здесь вырастет твоё.','Выбери участок. Добавляй столько грядок, сколько нужно.')+'<p class="note">Демонстрационная схема 50 участков. Цены примерные; реальная бронь и оплата пока не подключены.</p><div class="grid">'+Array.from({length:50},(_,i)=>{let n=i+1,owned=state.plots.some(p=>p.id===n);return `<div class="panel"><div class="row"><h3>Грядка №${String(n).padStart(2,'0')}</h3><span>${owned?'В хозяйстве':'Свободна · демо'}</span></div><p>6 м² · открытый грунт · место для камеры</p><div class="row"><strong>1 900 ₽ <small>/ месяц</small></strong><button class="btn" ${owned?'disabled':''} onclick="lease(${n})">${owned?'Добавлена':'Выбрать'}</button></div></div>`}).join('')+'</div>'}function lease(id){modalForm('Твоя новая грядка',`<p class="note">Демоаренда без оплаты и реального бронирования.</p><label>Название<input name="name" required maxlength="60" placeholder="Наш семейный огород"></label><label>Что выращиваем<select name="crop"><option>Томаты черри</option><option>Салат и пряные травы</option><option>Морковь и редис</option><option>Клубника</option></select></label><label>Текст таблички<input name="sign" required maxlength="40" value="Моя грядка"></label><button class="btn">Добавить в демохозяйство</button>`,f=>{state.plots.push({id,name:f.get('name'),crop:f.get('crop'),sign:f.get('sign'),size:6});location.hash='home';toast('Грядка добавлена в демохозяйство')})}function sign(id){let p=state.plots.find(p=>p.id===id);modalForm('Табличка на грядку',`<label>Надпись<input name="sign" maxlength="40" required value="${esc(p.sign)}"></label><p class="note">Предпросмотр на карточке. Физическую установку выполняет фермер после подключения сервиса.</p><button class="btn">Сохранить табличку</button>`,f=>p.sign=f.get('sign'))}function care(id){modalForm('Уход за грядкой №'+id,`<label>Задание<select name="action"><option>Проверить влажность и полить</option><option>Прополоть грядку</option><option>Проверить растения</option><option>Собрать урожай</option><option>Прислать фотоотчёт</option></select></label><label>Комментарий<input name="comment" maxlength="200" placeholder="Что нужно учесть"></label><p class="note">Задание появится в демокабинете фермера. Реальному фермеру оно пока не отправляется.</p><button class="btn">Создать задание</button>`,f=>{state.tasks.push({id:Date.now(),plot:id,text:f.get('action')+(f.get('comment')?' — '+f.get('comment'):''),done:false});toast('Задание добавлено')})}function camera(id){modalForm('Камера · грядка №'+id,`<div class="photo" style="border-radius:8px;background-image:url('${photos[id%2]}')"><span class="badge">ДЕМО · ФОТО, НЕ ПРЯМОЙ ЭФИР</span></div><p>Камера ещё не подключена.</p><p class="note">Для прямого эфира нужен адрес потока от установленной камеры. RTSP потребуется преобразовать в браузерный HLS/WebRTC.</p><button type="button" class="btn" onclick="modal.close()">Понятно</button>`,()=>{})}function market(){const all=[...products,...state.products];return heading('От своих — своим.','Продукты, семена и всё, что помогает расти.','<button class="btn" onclick="sell()">＋ Продать</button>')+`<div class="row"><div class="filters">${['Все','Продукты','Семена','Удобрения'].map(c=>`<button class="${c===category?'selected':''}" onclick="category='${c}';render()">${c}</button>`).join('')}</div><button class="btn light" onclick="cart()">Корзина · ${state.cart.length}</button></div><div class="grid marketgrid">${all.map((p,i)=>category==='Все'||p.cat===category?`<article class="card"><div class="producticon">${p.icon||'🌱'}</div><div class="cardbody"><small>${esc(p.cat)} · Демообъявление</small><h3>${esc(p.name)}</h3><p>${p.price} ₽ / ${esc(p.unit)}</p><button class="btn light" onclick="addCart(${i})">В корзину ＋</button></div></article>`:'').join('')}</div>`}function addCart(i){state.cart.push([...products,...state.products][i]);save();render();toast('Товар в демокорзине')}function cart(){modalForm('Корзина',state.cart.map((p,i)=>`<div class="event row"><span>${esc(p.name)} · ${p.price} ₽</span><button type="button" onclick="state.cart.splice(${i},1);save();modal.close();cart();render()">Убрать</button></div>`).join('')+`<h3>Итого: ${state.cart.reduce((s,p)=>s+Number(p.price),0)} ₽</h3><p class="note">Заказы и оплата ещё не подключены. Здесь можно собрать пробную корзину.</p><button type="button" class="btn" onclick="modal.close()">Продолжить выбор</button>`,()=>{})}function sell(){modalForm('Новое объявление','<label>Название<input name="name" required maxlength="80"></label><label>Категория<select name="cat"><option>Продукты</option><option>Семена</option><option>Удобрения</option></select></label><label>Цена, ₽<input type="number" name="price" min="1" max="1000000" required></label><label>Единица<input name="unit" value="кг" required maxlength="20"></label><p class="note">Объявление будет сохранено только в демоверсии этого браузера.</p><button class="btn">Добавить объявление</button>',f=>{state.products.push(Object.fromEntries(f));toast('Демообъявление добавлено')})}function farmer(){return heading('Хороший урожай начинается с заботы.','Кабинет фермера · демонстрация роли')+`<div class="stats"><div class="stat"><small>УЧАСТКОВ НА ФЕРМЕ</small><strong>50</strong></div><div class="stat"><small>В ДЕМОХОЗЯЙСТВЕ</small><strong>${state.plots.length}</strong></div><div class="stat"><small>ЗАДАНИЙ</small><strong>${state.tasks.length}</strong></div><div class="stat"><small>КАМЕР ПОДКЛЮЧЕНО</small><strong>0</strong></div></div><section class="panel"><h2>Задания по грядкам</h2>${state.tasks.map(t=>`<div class="event row"><span>№${t.plot} · ${esc(t.text)}</span><button class="btn light" ${t.done?'disabled':''} onclick="state.tasks.find(t=>t.id===${t.id}).done=true;save();render()">${t.done?'Выполнено':'Отметить выполненным'}</button></div>`).join('')||'<p>Пока нет заданий. Создай задание в разделе «Моё хозяйство».</p>'}</section>`}function render(){let route=location.hash.slice(1)||'home';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));$('#crumb').textContent=({home:'ОБЗОР',rent:'АРЕНДА',market:'МАРКЕТ',farmer:'ФЕРМЕР',animals:'ЖИВОТНЫЕ'})[route]||'ОБЗОР';$('#app').innerHTML=({home,rent,market,farmer,animals:()=>heading('У хозяйства — большое будущее.','Животные появятся на следующем этапе.')+'<section class="hero"><span class="eyebrow">СЛЕДУЮЩАЯ ГЛАВА FARM-OFF</span><h2>Свежие яйца. Своё молоко.<br>Знакомая ферма.</h2><p>Карточка животного, камера, дневник кормления и отчёты фермера.<br>Сейчас доступна аренда грядок в демонстрационном режиме.</p><a class="btn" href="#home">К моему хозяйству ↗</a></section>'}[route]||home)()}addEventListener('hashchange',()=>{render();scrollTo(0,0)});render();
